const $ = id => document.getElementById(id);
const HUBID = "sscng";

const EDITIONS = {
  be:  {label: "Basic Edition (be)",      bin: "stata"},
  se:  {label: "Standard Edition (se)",   bin: "stata-se"},
  mp:  {label: "MP-Parallel Edition (mp)", bin: "stata-mp"},
  all: {label: "All editions (one monolithic image)", bin: "stata-mp"},
};
const ED_ORDER = ["be", "se", "mp", "all"];
const FLAVORS = {
  "":         "standard (command line)",
  "i":        "interactive (-i, help files)",
  "x":        "graphical (-x)",
  "i-python": "interactive + Python",
};
const FLAVOR_ORDER = ["", "i", "i-python", "x"];
const NOTES = {
  x: "The graphical (-x) images carry the GUI binaries but NOT the X11 libraries " +
     "they need. Use them only as the FROM of an image that adds those libraries.",
  all: "Stata 18 and earlier were published as one monolithic image per version " +
       "with all editions and no -i, -x or -python variants.",
};

const rank = (list, k) => { const i = list.indexOf(k); return i < 0 ? list.length : i; };
const sortBy = (keys, order) => [...keys].sort((a, b) => rank(order, a) - rank(order, b) || a.localeCompare(b));
const esc = s => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const cm = s => `<span class="cm">${esc(s)}</span>`;
const kw = s => `<span class="kw">${esc(s)}</span>`;

function fill(sel, options, wanted) {
  const keep = options.some(o => o.value === wanted) ? wanted : options[0].value;
  sel.innerHTML = options.map(o => `<option value="${esc(o.value)}">${esc(o.label)}</option>`).join("");
  sel.value = keep;
  sel.disabled = options.length < 2;
}

function tagOptions(tags) {
  const dated = tags.filter(t => t !== "latest");
  const opts = dated.map((t, i) => ({value: t, label: i ? t : t + " (newest)"}));
  if (tags.includes("latest")) opts.push({value: "latest", label: "latest (moves; not reproducible)"});
  return opts;
}

const version = () => DATA.versions.find(v => v.key === $("vsel").value);

function onVersion() {
  const v = version();
  const eds = sortBy(Object.keys(v.editions), ED_ORDER);
  fill($("esel"), eds.map(e => ({value: e, label: (EDITIONS[e] || {label: e}).label})), $("esel").value || "se");
  onEdition();
}
function onEdition() {
  const flavors = sortBy(Object.keys(version().editions[$("esel").value]), FLAVOR_ORDER);
  fill($("fsel"), flavors.map(f => ({value: f, label: FLAVORS[f] || `-${f}`})), $("fsel").value);
  onFlavor();
}
function onFlavor() {
  const tags = version().editions[$("esel").value][$("fsel").value];
  fill($("tsel"), tagOptions(tags), $("tsel").value);
  render();
}

function render() {
  const v = version(), ed = $("esel").value, fl = $("fsel").value, tag = $("tsel").value;
  const suffix = (ed === "all" ? "" : "-" + ed) + (fl ? "-" + fl : "");
  const image = `${HUBID}/stata${v.key}${suffix}`;
  const bin = (EDITIONS[ed] || EDITIONS.mp).bin;

  $("pull").innerHTML =
    cm("# " + image + " on Docker Hub: https://hub.docker.com/r/" + image) + "\n" +
    `<span class="p">$</span> docker pull ${esc(image)}:${esc(tag)}`;

  const from = ed === "all"
    ? `FROM ${HUBID}/stata\${STATA_VERSION}:\${TAG}`
    : `FROM ${HUBID}/stata\${STATA_VERSION}-\${EDITION}\${FLAVOR}:\${TAG}`;
  const lines = [
    cm("# syntax=docker/dockerfile:1.2"),
    kw("ARG") + ` STATA_VERSION=${esc(v.key)}`,
  ];
  if (ed !== "all") {
    lines.push(kw("ARG") + ` EDITION=${esc(ed)}`);
    lines.push(kw("ARG") + ` FLAVOR=${esc(fl ? "-" + fl : "")}` + (fl ? "" : cm("   # standard flavor: no suffix")));
  }
  lines.push(
    kw("ARG") + ` TAG=${esc(tag)}`,
    kw("ARG") + ` STATA_BIN=${esc(bin)}`,
    "",
    kw(from.split(" ")[0]) + from.slice(4),
    "",
    cm("# Install the packages your project needs (see setup.do)"),
    kw("COPY") + " code/setup.do /setup.do",
    kw("RUN") + " --mount=type=secret,id=statalic,dst=/usr/local/stata/stata.lic \\",
    "    /usr/local/stata/${STATA_BIN} do /setup.do",
    "",
    kw("USER") + " statauser:stata",
    kw("VOLUME") + " /project",
    kw("WORKDIR") + " /project",
    cm("# Run the main file; mount the license at run time (never bake it in)"),
    kw("ENTRYPOINT") + ` ["${esc(bin)}", "-b", "main.do"]`,
  );
  $("dockerfile").innerHTML = lines.join("\n");

  const notes = [];
  if (fl === "x" && NOTES.x) notes.push(NOTES.x);
  if (ed === "all" && NOTES.all) notes.push(NOTES.all);
  $("note").hidden = !notes.length;
  $("note").textContent = notes.join(" ");
}

function copy(btnId, preId) {
  const btn = $(btnId);
  btn.addEventListener("click", () => {
    const text = $(preId).textContent;
    const done = () => { btn.textContent = "Copied"; setTimeout(() => btn.textContent = "Copy", 1500); };
    const fallback = () => {
      const ta = document.createElement("textarea");
      ta.value = text; document.body.appendChild(ta); ta.select();
      try { document.execCommand("copy"); done(); } catch (e) {}
      document.body.removeChild(ta);
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done).catch(fallback);
    } else fallback();
  });
}

function renderStats() {
  let images = 0, tags = 0;
  DATA.versions.forEach(v => Object.values(v.editions).forEach(e =>
    Object.values(e).forEach(t => { images++; tags += t.length; })));
  $("stats").innerHTML =
    `${images} images, ${tags} tags across ${DATA.versions.length} versions, read from ` +
    `<a href="https://hub.docker.com/u/sscng">Docker Hub</a> when this page was built ` +
    `(<code>${BUILD_STAMP}</code>). The page is rebuilt weekly and whenever the ` +
    `<a href="https://github.com/ssc-ng/docker-stata">repository</a> changes. ` +
    `Base images (<code>-base</code>) are building blocks only and are not listed.`;
}

(function init() {
  fill($("vsel"), DATA.versions.map(v => ({value: v.key, label: v.label})), "");
  $("vsel").addEventListener("change", onVersion);
  $("esel").addEventListener("change", onEdition);
  $("fsel").addEventListener("change", onFlavor);
  $("tsel").addEventListener("change", render);
  copy("copypull", "pull");
  copy("copydf", "dockerfile");
  renderStats();
  // newest version first; edition defaults to se, flavor to standard
  onVersion();
})();
